<?php
declare(strict_types=1);
namespace App\Services\Hrd;use App\Models\{PersonnelCashAdvance,PersonnelCashAdvancePayment,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class CashAdvanceService{public function transition(PersonnelCashAdvance $advance,string $action,User $actor):void{DB::transaction(function()use($advance,$action,$actor){$advance=PersonnelCashAdvance::lockForUpdate()->findOrFail($advance->id);$allowed=['approve'=>['pending','approved'],'reject'=>['pending','rejected'],'disburse'=>['approved','disbursed'],'cancel'=>['pending','cancelled']];[$from,$to]=$allowed[$action]??[null,null];if($advance->status!==$from)throw ValidationException::withMessages(['status'=>'Transisi status kasbon tidak valid.']);$data=['status'=>$to];if($action==='approve')$data+=['approved_by'=>$actor->id,'approved_at'=>now()];if($action==='reject')$data+=['rejected_by'=>$actor->id,'rejected_at'=>now()];if($action==='disburse')$data+=['disbursed_by'=>$actor->id,'disbursed_at'=>now(),'disbursement_date'=>today()];$advance->update($data);activity('hrd')->causedBy($actor)->performedOn($advance)->log('Status kasbon diubah menjadi '.$to.'.');});}
 public function pay(PersonnelCashAdvance $advance,float $amount,string $method,User $actor,?int $payrollId=null):PersonnelCashAdvancePayment{return DB::transaction(function()use($advance,$amount,$method,$actor,$payrollId){$advance=PersonnelCashAdvance::lockForUpdate()->findOrFail($advance->id);if(!in_array($advance->status,['disbursed','partially_paid'],true)||$amount<=0||$amount>(float)$advance->remaining_amount)throw ValidationException::withMessages(['amount'=>'Pembayaran melebihi sisa kasbon atau status kasbon tidak valid.']);$payment=PersonnelCashAdvancePayment::create(['cash_advance_id'=>$advance->id,'payroll_id'=>$payrollId,'payment_date'=>today(),'amount'=>$amount,'method'=>$method,'created_by'=>$actor->id]);$remaining=(float)$advance->remaining_amount-$amount;$advance->update(['remaining_amount'=>$remaining,'status'=>$remaining===0.0?'paid':'partially_paid']);activity('hrd')->causedBy($actor)->performedOn($advance)->log('Pembayaran kasbon dicatat.');return$payment;});}}
